  `StuID` NUMBER,
  `LName` TEXT,
  `Fname` TEXT,
  `Age` NUMBER,
  `Sex` TEXT,
  `Major` NUMBER,
  `Advisor` NUMBER,
  `city_code` TEXT,
  PRIMARY KEY (`StuID`)
);

CREATE TABLE `Dorm` (
  `dormid` NUMBER,
  `dorm_name` TEXT,
  `student_capacity` NUMBER,
  `gender` TEXT
);

CREATE TABLE `Dorm_amenity` (
  `amenid` NUMBER,
  `amenity_name` TEXT
);

CREATE TABLE `Has_amenity` (
  `dormid` NUMBER REFERENCES `Dorm`(`dormid`),
  `amenid` NUMBER REFERENCES `Dorm_amenity`(`amenid`)
);

CREATE TABLE `Lives_in` (
  `stuid` NUMBER REFERENCES `Student`(`StuID`),
  `dormid` NUMBER REFERENCES `Dorm`(`dormid`),
  `room_number` NUMBER
);

